'use strict';
const SurvivalEngine=(()=>{
 const clamp=n=>Math.max(0,Math.min(100,n)),clone=s=>JSON.parse(JSON.stringify(s));
 const hash=(seed,text)=>{let h=seed>>>0;for(const c of text)h=Math.imul(h^c.charCodeAt(0),16777619)>>>0;return h;};
 function create(party,seed=Date.now()>>>0){if(!Array.isArray(party)||party.length!==3||new Set(party).size!==3||party.some(id=>!survivalCast.some(p=>p.id===id)))throw Error('친구 3명을 골라주세요.');return {version:2,party:[...party],seed:seed>>>0,step:0,budget:120000,debt:0,delay:0,energy:68,fullness:30,mood:55,tension:14,history:[],incidents:[],actions:[],flags:[],personal:Object.fromEntries(party.map(id=>[id,60])),pending:null,phase:'choose'};}
 const has=(s,f)=>s.flags.includes(f);
 function ending(s){let id=null;if(has(s,'walkout')||s.tension>=75)id='split';else if(has(s,'evacuated'))id='evacuated';else if(s.energy<=0)id='exhausted';else if(s.fullness<=0)id='hungry';else if(s.step<7)return null;else if(s.debt>=30000)id='debt';else if((s.history.at(-1)?.choice==='oneMore'||s.delay>=105))id=has(s,'soaked')?'overnight':'taxi';else if(has(s,'rematch'))id=has(s,'won')?'champion':'revenge';else if(has(s,'abandoned')&&!has(s,'reconciled'))id='split';else if(has(s,'rescued')&&s.tension<35)id='rescued';else if(has(s,'reconciled')&&has(s,'blame')&&s.tension<65)id='reconciliation';else if(s.history.filter(h=>h.tags.includes('food')).length>=3&&s.fullness>=70)id='feast';else if(s.budget<10000)id='broke';else if(s.mood>=88&&s.energy>=40&&s.tension<35)id='perfect';else id='survived';return [id,...survivalEndingBook[id]];}
 function apply(s,c){const cost=c.cost||0;s.debt+=Math.max(0,cost-s.budget);s.budget=Math.max(0,s.budget-cost);for(const k of ['energy','fullness','mood'])s[k]=clamp(s[k]+(c[k]||0));s.tension=clamp(s.tension+(c.tension||0));}
 function choose(state,id){const s=clone(state);if(s.phase!=='choose'||ending(s))throw Error('선택할 차례가 아닙니다.');const scene=survivalScenes[s.step],c=scene.choices.find(c=>c.id===id);if(!c)throw Error('선택지를 확인해주세요.');apply(s,c);s.delay=Math.max(0,s.delay+({buffet:25,queue:50,walk:20,taxi:-10,nearby:-5,skip:-10,oneMore:120}[id]||0));let total=0;for(const pid of s.party){const p=survivalCast[pid];const pref=c.tags.reduce((sum,t)=>sum+(p.prefs[t]||0),0);s.personal[pid]=clamp(s.personal[pid]+Math.round(c.mood/2)+pref-(s.fullness<25?10:0)-(s.energy<25?7:0));total+=pref;}const affinity=Math.round(total/3);s.mood=clamp(s.mood+affinity);s.tension=clamp(s.tension+4+hash(s.seed,scene.id+':friction')%5+(s.debt>0?5:0)-(c.tags.includes('rest')?3:0)-(id==='plan'?6:0));if(s.party.some(id=>s.personal[id]<25))s.tension=clamp(s.tension+8);if(c.tags.includes('wait'))s.tension=clamp(s.tension+17);if(c.tags.includes('walk')&&s.energy<35)s.tension=clamp(s.tension+10);if(s.fullness<20)s.tension=clamp(s.tension+12);s.history.push({scene:scene.id,choice:id,affinity,tags:c.tags});s.actions.push({type:'choice',id});s.step++;if(s.step===2)s.pending=id==='buffet'?'bill':hash(s.seed,'first')%2?'booking':'wallet';if(s.step===5)s.pending=s.tension>=36||has(s,'abandoned')?'conflict':['pc','bowling'].includes(id)?'rivalry':'storm';s.phase='reaction';return s;}
 function resolve(state,id){const s=clone(state);if(s.phase!=='dilemma'||!s.pending)throw Error('돌발 상황이 아닙니다.');const d=survivalDilemmas[s.pending],c=d.choices.find(c=>c.id===id);if(!c)throw Error('선택지를 확인해주세요.');apply(s,c);s.delay+=({cover:10,refund:20,argue:25,detour:25,bench:15,blame:20,together:30,call:15,ignore:5,rematch:45,draw:5,taunt:15,shelter:20,adventure:35,evacuate:0,apologize:30,treat:15,double:15}[id]||0);s.flags.push(c.flag);if(c.flag==='walkout'&&s.tension<65)s.flags=s.flags.filter(f=>f!=='walkout');if(c.flag==='rematch'&&hash(s.seed,'match:'+s.history.map(h=>h.choice).join(','))%2)s.flags.push('won');if(c.flag==='reconciled'&&has(s,'abandoned'))s.flags.push('blame');for(const pid of s.party)s.personal[pid]=clamp(s.personal[pid]+(c.mood||0)+(['rescued','reconciled'].includes(c.flag)?10:0)-(c.tone==='fight'?15:0));s.incidents.push({id:s.pending,choice:id,step:s.step});s.actions.push({type:'dilemma',id});s.pending=null;s.phase='dilemmaReaction';return s;}
 function next(state){const s=clone(state);if(!['reaction','dilemmaReaction'].includes(s.phase))throw Error('대화를 먼저 확인해주세요.');s.phase=ending(s)?'end':s.pending?'dilemma':'choose';return s;}
 function restore(value){try{if(value?.version!==2||!Number.isInteger(value.seed)||!Array.isArray(value.actions)||value.actions.length>9)return null;let s=create(value.party,value.seed);for(const a of value.actions){s=a.type==='choice'?choose(s,a.id):a.type==='dilemma'?resolve(s,a.id):null;if(!s)return null;s=next(s);}if(['reaction','dilemmaReaction'].includes(value.phase)&&s.actions.length){const expected=s.actions.at(-1).type==='choice'?'reaction':'dilemmaReaction';if(value.phase!==expected)return null;s.phase=expected;}return s;}catch{return null;}}
 function incident(s){return survivalDilemmas[s.phase==='dilemma'?s.pending:s.incidents.at(-1)?.id];}
 function dialogue(s,endingMode=false){const stage=endingMode?'end:'+ending(s)[0]:s.phase+':'+s.step+':'+s.actions.map(a=>a.id).join('/');const order=[...s.party].sort((a,b)=>hash(s.seed,stage+a)-hash(s.seed,stage+b));let tone='';const dilemma=['dilemma','dilemmaReaction'].includes(s.phase),sc=survivalScenes[Math.min(6,s.phase==='reaction'?s.step-1:s.step)],h=s.history.at(-1);if(endingMode){tone=['split','exhausted','hungry'].includes(ending(s)[0])?'fight':['taxi','overnight'].includes(ending(s)[0])?'wild':'relief';}else if(s.phase==='dilemma')tone=incident(s).topic==='재대결'?'rival':s.tension>=25?'fight':'awkward';else if(s.phase==='dilemmaReaction'){const i=s.incidents.at(-1);tone=survivalDilemmas[i.id].choices.find(c=>c.id===i.choice).tone;}else if(s.tension>=40)tone='fight';else if(s.fullness<25)tone='hungry';else if(s.energy<30)tone='tired';else if(s.budget<20000)tone='poor';else if(s.phase==='reaction')tone=h.tags.includes('game')?'rival':h.tags.includes('walk')?'tired':h.tags.includes('food')?'rich':'relief';
 if(tone==='pivot'||tone==='leave')tone='relief';
 const turns=order.map((id,index)=>{const p=survivalCast[id],bank=survivalVoices[id],variant=hash(s.seed,stage+id)%2;let lines;const personalTone=!dilemma&&!endingMode&&s.personal[id]<30&&tone!=='hungry'&&tone!=='tired'?'awkward':tone;if(personalTone&&bank[personalTone])lines=bank[personalTone][variant];else lines=p.voices[sc.id];if(s.phase==='reaction'&&!['fight','hungry','tired','poor'].includes(personalTone)){const lastScene=survivalScenes[s.step-1],lastChoice=lastScene.choices.find(c=>c.id===h.choice),repeated=s.history.slice(0,-1).some(old=>survivalScenes.find(sc=>sc.id===old.scene).choices.find(c=>c.id===old.choice).reply===lastChoice.reply);if(lastChoice.reply==='plan'||(!repeated&&index!==1))lines=p.react[lastChoice.reply];}return {id,lines:[...lines]};});
 if(s.phase==='dilemma')for(const t of turns)t.lines=[...survivalIncidentLines[s.pending][t.id]];
 if(endingMode){const id=turns[0].id;turns[0].lines=[...survivalFinalLines[ending(s)[0]][[2,10,11].includes(id)?2:id===1?1:0]];}
 // Recall a concrete earlier decision in the selected speaker's own rhythm.
 if(!dilemma&&!endingMode&&s.step>=3){const memories=[];if(s.history.some(h=>h.choice==='buffet')&&s.budget<40000)memories.push('buffet');if(s.history.some(h=>h.choice==='queue'))memories.push('queue');if(has(s,'rescued'))memories.push('rescued');if(has(s,'blame')&&s.tension>20)memories.push('blame');if(memories.length){const speaker=turns[hash(s.seed,stage+'speaker')%turns.length];speaker.lines=[...survivalMemoryLines[memories[hash(s.seed,stage+'memory')%memories.length]][speaker.id]];}}

 return turns;}
 return {create,choose,resolve,next,ending,restore,incident,dialogue,hash};
})();
